def is_power_of_5(N):
    if N <= 0:
        return False
    if N == 1:
        return True # 5^0 = 1
    while N % 5 == 0:
        N //= 5
    return N == 1

results = {}
for n in range(3, 21):
    value = 2**n - 3
    is_power = is_power_of_5(value)
    results[n] = (value, is_power)

print(results)

def check(n):
    if n < 3 or n % 2 == 0:
        return None
    val = 2**n - 3
    if val <= 0:
        return None

    k = 0
    power_of_5 = 1
    while power_of_5 < val:
        power_of_5 *= 5
        k += 1

    if power_of_5 == val:
        return k
    else:
        return None

solutions = []
for n in [3, 5, 7, 9, 11, 13]: # Testing up to n=13
    k = check(n)
    if k is not None:
        solutions.append((n, k))

print(solutions)

def is_power_of_five(num):
    if num <= 0:
        return False
    while num > 1:
        if num % 5 != 0:
            return False
        num //= 5
    return True

# Test small even n >= 4
for n in range(4, 12, 2):
    result = (2**n) - 3
    is_power = is_power_of_five(result)
    print(f"n={n}: 2^{n} - 3 = {result}. Is power of 5? {is_power}")

def solve():
    for n in range(3, 1001):
        val = 2**n - 3
        if val > 0:
            # Check if val is a power of 5
            # 5^k = val => k = log5(val)
            k = 0
            temp_val = val
            is_power_of_5 = True
            if temp_val == 1:
                k = 0
            else:
                while temp_val > 1:
                    if temp_val % 5 != 0:
                        is_power_of_5 = False
                        break
                    temp_val //= 5
                    k += 1
                if temp_val != 1:
                    is_power_of_5 = False

            if is_power_of_5:
                print(f"n={n}, val={val}, k={k}")

solve()

